import { useEffect, useMemo, useState, useRef } from "react";
import {
  Form,
  Button,
  Row,
  Col,
  Container,
  Alert,
  Card,
  Nav,
  Navbar,
} from "react-bootstrap";
import { getSubjects } from "../api/api";
import { useNavigate } from "react-router-dom";

function SyllabusManager() {
  const inputRef = useRef(null);

  const navigate = useNavigate();
  const [subjects, setSubjects] = useState([]);
  const [error, setError] = useState("");

  const [search, setSearch] = useState("");
  const [semesterFilter, setSemesterFilter] = useState("");

  const loadCourses = () => {
    getSubjects()
      .then((data) => setSubjects(data))
      .catch(() => setError("Không thể tải danh sách khóa học."));
  };

  useEffect(() => {
    loadCourses();
  }, []);

  const semesters = useMemo(
    () => [...new Set(subjects.map((c) => c.semester))],
    [subjects],
  );

  const filteredCourses = useMemo(() => {
    const keyword = search.trim().toLowerCase();
    return subjects.filter((c) => {
      const matchesKeyword =
        !keyword ||
        c.code?.toLowerCase().includes(keyword) ||
        c.nameEn?.toLowerCase().includes(keyword) ||
        c.nameVi?.toLowerCase().includes(keyword);
      const matchesSemester = !semesterFilter || c.semester === semesterFilter;
      return matchesKeyword && matchesSemester;
    });
  }, [subjects, search, semesterFilter]);

  return (
    <Container className="py-4">
      <Navbar bg="dark" data-bs-theme="dark">
        <Container>
          <Nav className="me-auto">
            <h4 style={{ color: "whitesmoke" }}>
              FPT Education Learning Material Portal
            </h4>
          </Nav>
          <Nav className="me-auto">
            <Button onClick={() => navigate(`/login`)} variant="primary">
              Logout
            </Button>
          </Nav>
        </Container>
      </Navbar>
      <h2 className="mb-3">My Courses</h2>

      {error && <Alert variant="danger">{error}</Alert>}

      <Row className="mb-3 g-2 align-items-end">
        <Col>
          <strong>Search by:</strong>
        </Col>
        <Col md={4}>
          <Form.Select
            value={semesterFilter}
            onChange={(e) => setSemesterFilter(e.target.value)}
          >
            <option value="">Code</option>
            {semesters.map((s) => (
              <option key={s} value={s}>
                {s}
              </option>
            ))}
          </Form.Select>
        </Col>
        <Col md={5}>
          <Form.Control
            ref={inputRef}
            placeholder="Enter keyword..."
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </Col>

        <Col>
          {" "}
          <Button
            variant="info"
            onClick={() => {
              inputRef.current.focus();
              setSearch("");
              setSemesterFilter("");
            }}
          >
            Refresh
          </Button>
        </Col>
      </Row>

      {filteredCourses.length === 0 && (
        <div className="text-center text-muted py-4">
          Không có khóa học nào.
        </div>
      )}

      <Row>
        {filteredCourses.map((course) => (
          <Col md={4} className="mb-2" key={course.id}>
            <Card>
              <Card.Body>
                <div style={{ display: "flex", flexDirection: "column" }}>
                  <div
                    style={{ display: "flex", justifyContent: "space-between" }}
                  >
                    <p>{course.badge}</p>
                    <p>{course.category}</p>
                  </div>
                  <Card.Text>
                    {course.code}
                    <h5>{course.nameEn}</h5>
                    {course.nameVi}
                    <div className="text-muted small"></div>
                  </Card.Text>
                  <div
                    style={{ display: "flex", justifyContent: "space-between" }}
                  >
                    <strong>Get started</strong>
                    <Button
                      onClick={() => navigate(`/detail/${course.id}`)}
                      variant="primary"
                    >
                      →
                    </Button>
                  </div>
                </div>
              </Card.Body>
            </Card>
          </Col>
        ))}
      </Row>
    </Container>
  );
}

export default SyllabusManager;
